import { Link, useNavigate } from 'react-router-dom';
import { useCart } from '../context/CartContext';
import './CartPage.css';

export default function CartPage() {
  const { cart, update, remove, total } = useCart();
  const navigate = useNavigate();

  if (cart.items.length === 0)
    return (
      <div className="cart-empty">
        <h2>Your cart is empty</h2>
        <p>Looks like you haven't added anything yet.</p>
        <Link to="/products" className="btn btn-accent mt-3">Start Shopping</Link>
      </div>
    );

  return (
    <div className="cart-page">
      <h1 className="cart-title">Your Cart</h1>
      <div className="cart-layout">
        <div className="cart-items">
          {cart.items.map((item) => (
            <div className="cart-item" key={item._id}>
              <div className="cart-item-img" style={{ background: '#d4c4b8' }} />
              <div className="cart-item-info">
                <div className="cart-item-brand">{item.product?.brand}</div>
                <div className="cart-item-name">{item.product?.name}</div>
                {item.size && <div className="cart-item-meta">Size: {item.size}</div>}
                {item.color && <div className="cart-item-meta">Color: {item.color}</div>}
                <div className="cart-item-price">₹{item.product?.price?.toLocaleString()}</div>
              </div>
              <div className="cart-item-actions">
                <div className="qty-group">
                  <button className="qty-btn" onClick={() => item.quantity > 1 && update(item._id, item.quantity - 1)}>−</button>
                  <span className="qty-val">{item.quantity}</span>
                  <button className="qty-btn" onClick={() => update(item._id, item.quantity + 1)}>+</button>
                </div>
                <button className="cart-remove" onClick={() => remove(item._id)}>Remove</button>
              </div>
            </div>
          ))}
        </div>
        <div className="cart-summary">
          <h3>Order Summary</h3>
          <div className="summary-row"><span>Subtotal</span><span>₹{total.toLocaleString()}</span></div>
          <div className="summary-row"><span>Shipping</span><span>{total > 2999 ? 'Free' : '₹199'}</span></div>
          <div className="summary-row summary-total">
            <span>Total</span>
            <span>₹{(total > 2999 ? total : total + 199).toLocaleString()}</span>
          </div>
          <button className="btn btn-accent" style={{width:'100%',justifyContent:'center'}} onClick={() => navigate('/checkout')}>
            Proceed to Checkout
          </button>
          <Link to="/products" className="btn btn-outline mt-2" style={{width:'100%',justifyContent:'center'}}>
            Continue Shopping
          </Link>
        </div>
      </div>
    </div>
  );
}
